using System.Collections.Immutable;
using System.Reflection;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

public class A5_F2_AnalyzerClosedGenericStructFromMetadataTests
{
    private const string LibrarySource = """
using MessagePack;

namespace ReferencedLib
{
    public struct PlainGenericStruct<T>
    {
        public T Value;
    }

    public struct PlainGenericStruct2<T1, T2>
    {
        public T1 First;
        public T2 Second;
    }

    public record struct PlainGenericRecordStruct<T>(T Value);

    [MessagePackObject]
    public struct AttributedGenericStruct<T>
    {
        [Key(0)]
        public T Value;
    }

    [MessagePackObject]
    public struct AttributedGenericStruct2<T1, T2>
    {
        [Key(0)]
        public T1 First;

        [Key(1)]
        public T2 Second;
    }

    [MessagePackObject]
    public record struct AttributedGenericRecordStruct<T>([property: Key(0)] T Value);
}
""";

    private readonly ITestOutputHelper testOutputHelper;

    public A5_F2_AnalyzerClosedGenericStructFromMetadataTests(ITestOutputHelper testOutputHelper)
    {
        this.testOutputHelper = testOutputHelper;
    }

    [Fact]
    public async Task A5_F2_AttributedGenericStructsFromMetadata_AnalyzerDoesNotThrow()
    {
        string usageSource = """
using System;
using MessagePack;
using ReferencedLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public AttributedGenericStruct<int> A { get; set; }

        [Key(1)]
        public AttributedGenericStruct2<int, string> B { get; set; }

        [Key(2)]
        public AttributedGenericRecordStruct<long> C { get; set; }

        [Key(3)]
        public AttributedGenericStruct<AttributedGenericStruct<int>> D { get; set; }
    }
}
""";
        await this.RunAnalyzersAndAssertNoCrashAsync(usageSource);
    }

    [Fact]
    public async Task A5_F2_PlainGenericStructsFromMetadata_AnalyzerDoesNotThrow()
    {
        string usageSource = """
using System;
using MessagePack;
using ReferencedLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public PlainGenericStruct<int> A { get; set; }

        [Key(1)]
        public PlainGenericStruct2<int, string> B { get; set; }

        [Key(2)]
        public PlainGenericRecordStruct<long> C { get; set; }
    }
}
""";
        await this.RunAnalyzersAndAssertNoCrashAsync(usageSource);
    }

    private static System.Collections.Generic.List<MetadataReference> GetBaseReferences()
    {
        var paths = new System.Collections.Generic.Dictionary<string, string>(System.StringComparer.OrdinalIgnoreCase);

        if (System.AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string p in tpa.Split(System.IO.Path.PathSeparator))
            {
                if (p.Length > 0 && p.EndsWith(".dll", System.StringComparison.OrdinalIgnoreCase))
                {
                    paths[System.IO.Path.GetFileName(p)] = p;
                }
            }
        }

        foreach (Assembly a in System.AppDomain.CurrentDomain.GetAssemblies())
        {
            AddAssembly(paths, a);
        }

        foreach (string name in new[] { "netstandard", "System.Runtime", "MessagePack.Annotations", "MessagePack" })
        {
            try
            {
                AddAssembly(paths, Assembly.Load(new AssemblyName(name)));
            }
            catch (System.Exception)
            {
                // Not available in this runtime; ignore.
            }
        }

        var refs = new System.Collections.Generic.List<MetadataReference>();
        foreach (string p in paths.Values)
        {
            refs.Add(MetadataReference.CreateFromFile(p));
        }

        return refs;
    }

    private static void AddAssembly(System.Collections.Generic.Dictionary<string, string> paths, Assembly a)
    {
        try
        {
            if (!a.IsDynamic && !string.IsNullOrEmpty(a.Location) && System.IO.File.Exists(a.Location))
            {
                string fileName = System.IO.Path.GetFileName(a.Location);
                if (!paths.ContainsKey(fileName))
                {
                    paths[fileName] = a.Location;
                }
            }
        }
        catch (System.Exception)
        {
            // ignore assemblies whose location cannot be determined.
        }
    }

    private static ImmutableArray<DiagnosticAnalyzer> GetMessagePackAnalyzers()
    {
        var assemblies = new System.Collections.Generic.List<Assembly>
        {
            typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly,
        };
        try
        {
            Assembly extra = Assembly.Load(new AssemblyName("MessagePack.Analyzers"));
            if (!assemblies.Contains(extra))
            {
                assemblies.Add(extra);
            }
        }
        catch (System.Exception)
        {
            // optional assembly
        }

        var builder = ImmutableArray.CreateBuilder<DiagnosticAnalyzer>();
        foreach (Assembly asm in assemblies)
        {
            System.Type[] types;
            try
            {
                types = asm.GetTypes();
            }
            catch (ReflectionTypeLoadException ex)
            {
                types = ex.Types;
            }

            foreach (System.Type t in types)
            {
                if (t is null || t.IsAbstract || !typeof(DiagnosticAnalyzer).IsAssignableFrom(t))
                {
                    continue;
                }

                if (t.GetCustomAttribute<DiagnosticAnalyzerAttribute>() is null || t.GetConstructor(System.Type.EmptyTypes) is null)
                {
                    continue;
                }

                builder.Add((DiagnosticAnalyzer)System.Activator.CreateInstance(t)!);
            }
        }

        return builder.ToImmutable();
    }

    private async Task RunAnalyzersAndAssertNoCrashAsync(string usageSource)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        var compilationOptions = new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary);
        System.Collections.Generic.List<MetadataReference> baseRefs = GetBaseReferences();

        // Build the referenced assembly and consume it purely as metadata.
        CSharpCompilation libCompilation = CSharpCompilation.Create(
            "ReferencedLib",
            new[] { CSharpSyntaxTree.ParseText(LibrarySource, parseOptions) },
            baseRefs,
            compilationOptions);

        MetadataReference libReference;
        using (var ms = new System.IO.MemoryStream())
        {
            var emitResult = libCompilation.Emit(ms);
            foreach (Diagnostic d in emitResult.Diagnostics)
            {
                if (d.Severity == DiagnosticSeverity.Error)
                {
                    this.testOutputHelper.WriteLine("Library: " + d.ToString());
                }
            }

            Assert.True(emitResult.Success, "The referenced library failed to compile.");
            libReference = MetadataReference.CreateFromImage(ms.ToArray());
        }

        var refs = new System.Collections.Generic.List<MetadataReference>(baseRefs) { libReference };
        CSharpCompilation compilation = CSharpCompilation.Create(
            "TempProject",
            new[] { CSharpSyntaxTree.ParseText(usageSource, parseOptions) },
            refs,
            compilationOptions);

        bool hasCompileErrors = false;
        foreach (Diagnostic d in compilation.GetDiagnostics())
        {
            if (d.Severity == DiagnosticSeverity.Error)
            {
                hasCompileErrors = true;
                this.testOutputHelper.WriteLine("Usage: " + d.ToString());
            }
        }

        Assert.False(hasCompileErrors, "The usage source failed to compile.");

        ImmutableArray<DiagnosticAnalyzer> analyzers = GetMessagePackAnalyzers();
        Assert.False(analyzers.IsEmpty, "No MessagePack analyzers were found.");

        var exceptions = new System.Collections.Generic.List<System.Exception>();
        var options = new CompilationWithAnalyzersOptions(
            new AnalyzerOptions(ImmutableArray<AdditionalText>.Empty),
            (ex, analyzer, diag) =>
            {
                lock (exceptions)
                {
                    exceptions.Add(ex);
                }
            },
            concurrentAnalysis: false,
            logAnalyzerExecutionTime: false);

        CompilationWithAnalyzers withAnalyzers = compilation.WithAnalyzers(analyzers, options);
        ImmutableArray<Diagnostic> diagnostics = await withAnalyzers.GetAnalyzerDiagnosticsAsync();

        foreach (Diagnostic d in diagnostics)
        {
            this.testOutputHelper.WriteLine(d.ToString());
        }

        foreach (System.Exception ex in exceptions)
        {
            this.testOutputHelper.WriteLine(ex.ToString());
        }

        Assert.Empty(exceptions);
        Assert.DoesNotContain(diagnostics, d => d.Id == "AD0001");
    }
}
